update public.quizzes set questions = $quiz$[{"correct": 1, "fun_fact": "It was the group's first studio album, released digitally on March 14, 2022 and on CD the following day.", "options": ["2021", "March 2022", "November 2022", "2023"], "question": "When was (G)I-DLE's I NEVER DIE album (TOMBOY era) released?"}, {"correct": 2, "fun_fact": "Samson of High Quality Fish directed its music video, which passed 200 million YouTube views on January 17, 2023.", "options": ["HWAA", "Nxde", "TOMBOY", "MY BAG"], "question": "What was the lead single from I NEVER DIE?"}, {"correct": 1, "fun_fact": "Its inspiration was the fictional villain Cruella de Vil, and Billboard later named it the best K-pop song of 2022.", "options": ["Romantic love", "Defiance of gender norms and labels, doing whatever you want", "Grief and loss", "Patriotism"], "question": "What themes define TOMBOY?"}, {"correct": 3, "fun_fact": "On the Gaon Digital Chart, now the Circle Digital Chart, it rose to number one in its second week and ranked second for all of 2022.", "options": ["Song of the Year", "Record of the Year", "Best Collaboration", "Music Video of the Year"], "question": "Which prize did TOMBOY win at the 2022 Melon Music Awards in South Korea?"}, {"correct": 2, "fun_fact": "Minnie made her solo debut with the EP Her on January 21, 2025.", "options": ["Violin", "Guitar", "Piano", "Cello"], "question": "Which instrument has Minnie played since childhood and uses to write songs?"}, {"correct": 1, "fun_fact": "Soyeon, the group's leader, won Best Songwriter at the Melon Music Awards in 2022 and again in 2024.", "options": ["Miyeon", "Soyeon", "Minnie", "Shuhua"], "question": "Which (G)I-DLE member is the primary songwriter and producer?"}, {"correct": 1, "fun_fact": "The five were Miyeon, Minnie, Soyeon, Yuqi and Shuhua, and the same five took the new group name i-dle in May 2025.", "options": ["6", "5", "4", "7"], "question": "How many members does (G)I-DLE have during the TOMBOY era?"}, {"correct": 1, "fun_fact": "The group also performed it on M Countdown and at the 37th Golden Disc Awards, alongside the lead single and My Bag.", "options": ["Already", "VILLAIN DIES", "My Bag", "Oh My God"], "question": "Which I NEVER DIE track blends dark electro-pop with hip-hop, rock and violin?"}, {"correct": 2, "fun_fact": "That edition, held at the Kyocera Dome Osaka in Japan, was the first under the new MAMA Awards name.", "options": ["Best Female Group", "Artist of the Year", "Favorite Female Group", "Song of the Year"], "question": "Which award did (G)I-DLE win at the 2022 MAMA Awards?"}, {"correct": 1, "fun_fact": "HWAA came out on January 11, 2021 as the lead single of the EP I Burn and peaked at number four on the Gaon Digital Chart, a first top five hit for the group.", "options": ["Latata era", "HWAA era", "Oh My God era", "Lion era"], "question": "What era preceded TOMBOY that showed (G)I-DLE's traditional/ethnic concept?"}]$quiz$::jsonb
where id = 'e9d14fb3-d6a3-43f6-9617-0bdb5daab8df' and slug = 'gi-dle-the-tomboy-era';

