update public.quizzes set questions = $quiz$[{"correct": 2, "fun_fact": "Dynamite crossed one billion Spotify streams on July 20, 2021, less than a year after its August 2020 release.", "options": ["BLACKPINK - DDU-DU DDU-DU", "PSY - Gangnam Style", "BTS - Dynamite", "BLACKPINK - Kill This Love"], "question": "Which K-pop song was the first by any K-pop act to surpass 1 billion streams on Spotify?"}, {"correct": 3, "fun_fact": "ILLIT, formed through the 2023 survival show R U Next?, debuted on March 25, 2024, and Magnetic went on to top the Circle Digital Chart.", "options": ["TWICE", "aespa", "Girls' Generation", "ILLIT"], "question": "Which girl group's debut single, Magnetic, was among Spotify's 10 most-streamed K-pop songs worldwide in 2024?"}, {"correct": 1, "fun_fact": "Its agency, Big Hit Entertainment, counted 7,778,950 streams for the song on release day, the best opening day for a K-pop song on Spotify that year.", "options": ["Spotify US Top 50", "Spotify Global Daily Top Songs", "Spotify Viral 50", "Spotify New Music Friday"], "question": "Dynamite by BTS debuted at number one on which Spotify chart, a historic first for a K-pop act?"}, {"correct": 1, "fun_fact": "It got there in March 2024; BLACKPINK member Lisa had already passed the mark as a soloist with Money in 2023.", "options": ["First K-pop song to reach 1 billion streams", "First K-pop girl group song to reach 1 billion Spotify streams", "First girl group song to debut at #1 on Spotify Global", "First K-pop song to top the Billboard Hot 100"], "question": "BLACKPINK's How You Like That reached 1 billion Spotify streams. What milestone did it achieve as a K-pop girl group song?"}, {"correct": 1, "fun_fact": "In 2014 it also became the first video to pass two billion views, a milestone YouTube marked with a second dancing PSY animation.", "options": ["November 2012", "December 2012", "January 2013", "March 2013"], "question": "PSY's Gangnam Style was the first YouTube video to reach 1 billion views. When did it achieve this milestone?"}, {"correct": 2, "fun_fact": "Released in July 2023, Seven also reached number one on the Billboard Hot 100 and the Billboard Global 200.", "options": ["Standing Next to You", "3D", "Seven", "Dreamers"], "question": "Jungkook became the first K-pop soloist to pass 2 billion Spotify streams with which single?"}, {"correct": 0, "fun_fact": "BTS topped that Spotify Wrapped list again, and SEVENTEEN, at number 10, was the only other boy group in it.", "options": ["Stray Kids", "ATEEZ", "TXT", "ENHYPEN"], "question": "Which boy group ranked third among Spotify's most-streamed K-pop acts worldwide in 2024?"}, {"correct": 1, "fun_fact": "It entered the Global 200 at number 116 and peaked at number 52 during that 42 week run.", "options": ["Most streams in one week by K-pop group", "Longest-charting song by a K-pop female act (42 weeks)", "First K-pop girl group song at #1", "Most-streamed debut song ever"], "question": "NewJeans' Hype Boy broke which streaming record on the Billboard Global 200?"}, {"correct": 1, "fun_fact": "They passed the previous holder, the British group Little Mix, by about 400 million streams, according to Guinness World Records.", "options": ["5.5 billion", "8.8 billion", "12 billion", "3.2 billion"], "question": "BLACKPINK set a Guinness World Record in 2023 by becoming the most-streamed female band on Spotify. How many streams did they have at that point?"}, {"correct": 2, "fun_fact": "TikTok users had put the song in eight million videos by May 2023, and it later climbed to number 17 on the Billboard Hot 100.", "options": ["Twitter/X", "Instagram", "TikTok", "YouTube Shorts"], "question": "A sped-up version of FIFTY FIFTY's Cupid went viral on which platform in 2023?"}]$quiz$::jsonb
where id = 'bf101f43-30ff-4665-b85e-97a7fb0c105b' and slug = 'k-pop-streaming-records';

